#include "mspa/psychology/appraisal.hpp"
#include "mspa/psychology/personality.hpp"
#include <algorithm>
#include <cmath>
namespace mspa {
AppraisalVector AppraisalEngine::evaluate(const AgentPsychState&a,const Proposition&p,const RegistrySnapshot&r,const AppraisalContext&ctx)const{AppraisalVector v{};const auto*s=r.find(p.predicate);v.relevance=s?s->default_relevance:0.2f;v.consequence=(s?s->default_consequence:0.0f)*(p.positive?1.0f:-1.0f);v.intentionality=s?s->intentionality:0.0f;v.certainty=std::clamp(ctx.perceived_certainty,0.0f,1.0f);const auto pd=PersonalitySystem{}.derive(a.personality);v.control=ctx.perceived_control>=0?std::clamp(ctx.perceived_control,0.0f,1.0f):std::clamp(0.45f*a.personality.boldness+0.35f*a.personality.persistence+0.2f*a.personality.stability,0.0f,1.0f);v.expectation_error=std::clamp(std::abs(v.consequence-ctx.expected_consequence),0.0f,1.0f);if(s){for(auto c:s->related_concepts){for(const auto&x:a.values)if(x.concept_id==c)v.relevance=std::clamp(v.relevance+0.25f*x.intensity,0.0f,1.0f);for(const auto&g:a.goals)if(g.concept_id==c&&g.active())v.relevance=std::clamp(v.relevance+0.3f*g.priority,0.0f,1.0f);}for(const auto&h:s->appraisal_hints){if(h=="threat")v.consequence=std::min(v.consequence,-0.65f);else if(h=="benefit")v.consequence=std::max(v.consequence,0.65f);else if(h=="norm_violation")v.norm_alignment=-1.0f;else if(h=="norm_support")v.norm_alignment=1.0f;else if(h=="unexpected")v.expectation_error=std::max(v.expectation_error,0.75f);}if(!s->agency_role.empty()&&find_argument(p,s->agency_role))v.agency=1.0f;for(const auto&role:s->target_roles){if(const auto*arg=find_argument(p,role);arg&&arg->has_agent){auto rel=std::find_if(a.relationships.begin(),a.relationships.end(),[&](const auto&x){return x.other==arg->agent;});if(rel!=a.relationships.end())v.relationship=std::clamp(0.4f*rel->affection+0.25f*rel->trust+0.2f*rel->respect+0.15f*rel->familiarity,-1.0f,1.0f);}}}v.relevance=std::clamp(v.relevance*(0.85f+0.15f*(1.0f+pd.threat_sensitivity*(v.consequence<0?1.0f:0.0f))),0.0f,1.0f);v.consequence=std::clamp(v.consequence,-1.0f,1.0f);return v;}
}
